const mediaQuery = `
  query($cursor: String) {
    files(first: 250, after: $cursor, query: "media_type:IMAGE OR media_type:VIDEO") {
      edges {
        node {
          ... on MediaImage {
            id
            alt
            image {
              url
              width
              height
            }
            createdAt
          }
          ... on Video {
            id
            alt
            sources {
              url
              mimeType
              format
              height
              width
            }
            createdAt
          }
          ... on GenericFile {
            id
            alt
            url
            createdAt
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const menusQuery = `
  query {
    menus(first: 250) {
      edges {
        node {
          id
          handle
          title
          items {
            id
            title
            url
            type
            resourceId
            items {
              id
              title
              url
              type
              resourceId
            }
          }
        }
      }
    }
  }
`;

function createNoopLogger() {
  return {
    info() {},
    success() {},
    warn() {},
    error() {},
    verbose() {}
  };
}

function createExportError(objectType, error) {
  return {
    objectType,
    status: 'failed',
    filepath: null,
    count: 0,
    warnings: [],
    errors: [error.message]
  };
}

function normalizeExportOptions(outputPathOrOptions) {
  if (typeof outputPathOrOptions === 'string' || typeof outputPathOrOptions === 'undefined') {
    return { outputPath: outputPathOrOptions };
  }

  return { ...outputPathOrOptions };
}

async function fetchPaginatedData(store, query, dataKey, deps = {}) {
  const request = deps.graphqlRequest || graphqlRequest;
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };

  let allData = [];
  let hasNextPage = true;
  let cursor = null;

  while (hasNextPage) {
    const data = await request(url, query, { cursor }, headers);
    const result = data[dataKey];

    if (!result) {
      throw new Error(`Invalid response: missing ${dataKey} in response`);
    }

    allData = allData.concat(result.edges.map((edge) => edge.node));
    hasNextPage = result.pageInfo?.hasNextPage ?? false;
    cursor = result.pageInfo?.endCursor ?? null;
  }

  return allData;
}

async function fetchMenus(store, deps = {}) {
  const request = deps.graphqlRequest || graphqlRequest;
  const url = buildAdminGraphqlUrl(store);
  const headers = { 'X-Shopify-Access-Token': store.api_key };
  const data = await request(url, menusQuery, {}, headers);
  return data.menus.edges.map((edge) => edge.node);
}

function createDataFetchers(deps = {}) {
  return {
    pages: (store) => fetchPaginatedData(store, pagesQuery, 'pages', deps),
    products: (store) => fetchPaginatedData(store, productsQuery, 'products', deps),
    collections: (store) => fetchPaginatedData(store, collectionsQuery, 'collections', deps),
    blogs: (store) => fetchPaginatedData(store, blogsQuery, 'blogs', deps),
    articles: (store) => fetchPaginatedData(store, articlesQuery, 'articles', deps),
    media: (store) => fetchPaginatedData(store, mediaQuery, 'files', deps),
    menus: (store) => fetchMenus(store, deps)
  };
}

function getFilenameFromUrl(url) {
  try {
    const urlObj = new URL(url);
    const basename = path.basename(urlObj.pathname);
    if (basename && basename !== '/' && !basename.startsWith('?')) {
      return decodeURIComponent(basename);
    }
    return null;
  } catch {
    return null;
  }
}

function getExtensionFromUrl(url) {
  try {
    const urlObj = new URL(url);
    const ext = path.extname(urlObj.pathname);
    if (ext) {
      return ext;
    }
    const format = urlObj.searchParams.get('format');
    return format ? `.${format}` : '.bin';
  } catch {
    return '.bin';
  }
}

function sanitizeFilename(name) {
  return name.replace(/[^a-zA-Z0-9-_\.]/g, '_').substring(0, 200);
}

function generateUniqueFilename(baseName, existingNames) {
  if (!existingNames.has(baseName)) {
    existingNames.add(baseName);
    return baseName;
  }

  const ext = path.extname(baseName);
  const nameWithoutExt = path.basename(baseName, ext);
  let counter = 1;
  let candidate;

  do {
    candidate = `${nameWithoutExt}_${counter}${ext}`;
    counter += 1;
  } while (existingNames.has(candidate));

  existingNames.add(candidate);
  return candidate;
}

async function downloadFile(url, destPath, deps = {}) {
  if (deps.downloadFile) {
    return deps.downloadFile(url, destPath);
  }

  const fsModule = deps.fsSync || fsSync;
  const fsPromises = deps.fs || fs;

  return new Promise((resolve, reject) => {
    const protocol = url.startsWith('https') ? https : http;
    const file = fsModule.createWriteStream(destPath);

    const request = protocol.get(url, (response) => {
      if (response.statusCode === 301 || response.statusCode === 302) {
        file.close();
        fsModule.unlinkSync(destPath);
        downloadFile(response.headers.location, destPath, deps).then(resolve).catch(reject);
        return;
      }

      if (response.statusCode !== 200) {
        file.close();
        fsModule.unlinkSync(destPath);
        reject(new Error(`HTTP ${response.statusCode}: Failed to download`));
        return;
      }

      response.pipe(file);
      file.on('finish', () => {
        file.close();
        resolve(destPath);
      });
    });

    request.on('error', (error) => {
      file.close();
      fsPromises.unlink(destPath).catch(() => {});
      reject(error);
    });

    file.on('error', (error) => {
      file.close();
      fsPromises.unlink(destPath).catch(() => {});
      reject(error);
    });

    request.setTimeout(60000, () => {
      request.destroy();
      file.close();
      fsPromises.unlink(destPath).catch(() => {});
      reject(new Error('Download timeout'));
    });
  });
}

async function exportMediaWithFiles(store, outputPath, timestamp, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const mediaDir = path.join(outputPath, MEDIA_SUBDIR, timestamp);
  await ensureDirectory(mediaDir, deps);
  const dataFetchers = deps.dataFetchers || createDataFetchers(deps);

  logger.info('Export', `Fetching media metadata from ${store.store_name}...`);
  const mediaItems = await dataFetchers.media(store);
  logger.info('Export', `Found ${mediaItems.length} media items. Downloading files...`);

  const exportedMedia = [];
  const usedFilenames = new Set();
  let downloaded = 0;
  let failed = 0;

  for (const item of mediaItems) {
    let originalUrl = null;
    let mediaType = 'unknown';

    if (item.image?.url) {
      originalUrl = item.image.url;
      mediaType = 'image';
    } else if (item.sources?.[0]?.url) {
      originalUrl = item.sources[0].url;
      mediaType = 'video';
    } else if (item.url) {
      originalUrl = item.url;
      mediaType = 'file';
    }

    if (!originalUrl) {
      logger.warn('Export', `Skipping media item ${item.id}: no URL found`);
      failed += 1;
      continue;
    }

    let filename = getFilenameFromUrl(originalUrl);
    if (!filename) {
      const ext = getExtensionFromUrl(originalUrl);
      const idPart = String(item.id || '').split('/').pop();
      filename = `${idPart}${ext}`;
    }

    filename = generateUniqueFilename(sanitizeFilename(filename), usedFilenames);
    const localPath = path.join(mediaDir, filename);
    const relativePath = path.join(MEDIA_SUBDIR, timestamp, filename);

    try {
      await downloadFile(originalUrl, localPath, deps);
      downloaded += 1;

      if (downloaded % 10 === 0) {
        logger.info('Export', `Downloaded ${downloaded}/${mediaItems.length} media files...`);
      }

      exportedMedia.push({
        ...item,
        mediaType,
        originalUrl,
        localPath: relativePath,
        filename
      });
    } catch (error) {
      logger.warn('Export', `Failed to download ${item.id}: ${error.message}`);
      failed += 1;
      exportedMedia.push({
        ...item,
        mediaType,
        originalUrl,
        localPath: null,
        downloadError: error.message
      });
    }
  }

  logger.info('Export', `Media download complete: ${downloaded} downloaded, ${failed} failed`);

  return {
    items: exportedMedia,
    mediaDir: path.join(MEDIA_SUBDIR, timestamp),
    stats: { total: mediaItems.length, downloaded, failed }
  };
}

async function exportObjects(store, objectTypes, outputPathOrOptions, deps = {}) {
  const logger = deps.logger || createNoopLogger();
  const fsPromises = deps.fs || fs;
  const dataFetchers = deps.dataFetchers || createDataFetchers(deps);
  const options = normalizeExportOptions(outputPathOrOptions);
  const outputPath = options.outputPath;
  const timestamp = options.timestamp || generateTimestamp();
  const results = [];
  const warnings = [];
  const errors = [];

  await ensureDirectory(outputPath, deps);

  for (const objectType of objectTypes) {
    if (!VALID_EXPORT_OBJECT_TYPES.includes(objectType)) {
      const warning = `Skipping unknown object type: ${objectType}`;
      logger.warn('Export', warning);
      warnings.push(warning);
      results.push({
        objectType,
        status: 'skipped',
        filepath: null,
        count: 0,
        warnings: [warning],
        errors: []
      });
      continue;
    }

    try {
      if (objectType === 'media') {
        logger.info('Export', `Exporting media with files from ${store.store_name}...`);
        const mediaResult = await exportMediaWithFiles(store, outputPath, timestamp, {
          ...deps,
          logger
        });
        const exportData = {
          version: EXPORT_VERSION,
          store: store.store_url,
          storeName: store.store_name,
          objectType: 'media',
          createdAt: new Date().toISOString(),
          count: mediaResult.items.length,
          mediaDir: mediaResult.mediaDir,
          stats: mediaResult.stats,
          data: mediaResult.items
        };
        const filename = generateFilename(store.store_name, 'media', timestamp);
        const filepath = path.join(outputPath, filename);
        await fsPromises.writeFile(filepath, JSON.stringify(exportData, null, 2), 'utf8');
        logger.success('Export', `Exported ${mediaResult.stats.downloaded} media files to ${filepath}`);
        results.push({
          objectType: 'media',
          status: 'success',
          filepath,
          count: mediaResult.items.length,
          downloaded: mediaResult.stats.downloaded,
          failed: mediaResult.stats.failed,
          warnings: [],
          errors: []
        });
        continue;
      }

      const fetcher = dataFetchers[objectType];
      if (!fetcher) {
        const warning = `No data fetcher available for: ${objectType}`;
        logger.warn('Export', warning);
        warnings.push(warning);
        results.push({
          objectType,
          status: 'skipped',
          filepath: null,
          count: 0,
          warnings: [warning],
          errors: []
        });
        continue;
      }

      logger.info('Export', `Fetching ${objectType} from ${store.store_name}...`);
      const data = await fetcher(store);
      const exportData = {
        version: EXPORT_VERSION,
        store: store.store_url,
        storeName: store.store_name,
        objectType,
        createdAt: new Date().toISOString(),
        count: data.length,
        data
      };
      const filename = generateFilename(store.store_name, objectType, timestamp);
      const filepath = path.join(outputPath, filename);
      await fsPromises.writeFile(filepath, JSON.stringify(exportData, null, 2), 'utf8');
      logger.success('Export', `Exported ${data.length} ${objectType} to ${filepath}`);
      results.push({
        objectType,
        status: 'success',
        filepath,
        count: data.length,
        warnings: [],
        errors: []
      });
    } catch (error) {
      logger.error('Export', `Failed to export ${objectType}: ${error.message}`);
      errors.push(`${objectType}: ${error.message}`);
      results.push(createExportError(objectType, error));
    }
  }

  return {
    success: errors.length === 0,
    results,
    warnings,
    errors
  };
}

module.exports = {
  VALID_EXPORT_OBJECT_TYPES,
  createDataFetchers,
  exportMediaWithFiles,
  exportObjects,
  fetchMenus,
  fetchPaginatedData
};
